// NOTE (Oct 22, 2026): the live deployment uses a delegate key generated by the MemWal dashboard instead
// (MEMWAL_AGENT_ID 1e8021…2677). The delegate file this script wrote earlier was never registered and is unused.
// Generate the two keys Sentinel Memory needs, offline, on this machine. It never prints a private key.
//   1. Owner wallet: a fresh Sui ed25519 keypair. It owns the MemWal account. You import it into a Sui wallet
//      extension and "Connect wallet" at https://memory.walrus.xyz. MemWal sponsors the gas, so it needs no SUI.
//   2. Delegate key: the ed25519 key the agent signs relayer requests with. Its public key is MEMWAL_AGENT_ID.
//      Import it in the MemWal setup wizard ("import existing delegate key") so it gets registered on-chain.
// Usage: bun scripts/gen-keys.ts [/path/to/wallet-dir]. It refuses to overwrite existing files.
import { existsSync, mkdirSync, writeFileSync, chmodSync } from 'node:fs'
import { join } from 'node:path'
import { Ed25519Keypair } from '@mysten/sui/keypairs/ed25519'

const dir = process.argv[2] ?? '/workspace/crypto-earn/wallet'
mkdirSync(dir, { recursive: true, mode: 0o700 })
chmodSync(dir, 0o700)
const ownerFile = join(dir, 'sui_memwal_owner.json')
const delegateFile = join(dir, 'memwal_delegate.json')
for (const f of [ownerFile, delegateFile]) if (existsSync(f)) { console.error(`refusing to overwrite ${f}`); process.exit(1) }

const owner = Ed25519Keypair.generate()
writeFileSync(ownerFile, JSON.stringify({ purpose: 'Sui mainnet owner wallet for the Walrus Memory (MemWal) account used by Sentinel Memory', scheme: 'ED25519', address: owner.toSuiAddress(), suiPrivateKey: owner.getSecretKey(), createdAt: new Date().toISOString() }, null, 1), { mode: 0o600 })
chmodSync(ownerFile, 0o600)

const delegate = Ed25519Keypair.generate()
const { secretKey } = (await import('@mysten/sui/cryptography')).decodeSuiPrivateKey(delegate.getSecretKey())
const privHex = Buffer.from(secretKey).toString('hex')
const pubHex = Buffer.from(delegate.getPublicKey().toRawBytes()).toString('hex')
writeFileSync(delegateFile, JSON.stringify({ purpose: 'Walrus Memory delegate key for Sentinel Memory (MEMWAL_PRIVATE_KEY)', privateKeyHex: privHex, publicKeyHex: pubHex, createdAt: new Date().toISOString() }, null, 1), { mode: 0o600 })
chmodSync(delegateFile, 0o600)

console.log(`owner Sui address:              ${owner.toSuiAddress()}`)
console.log(`delegate public key (AGENT_ID): ${pubHex}`)
console.log(`private keys written (chmod 600) to ${ownerFile} and ${delegateFile}. They are not printed.`)
